        }

        uint256 balanceAfter = c.balanceOf(burner);

        // The general rule: if the burn caller is NOT the owner, the balance must NOT decrease.
        // The owner is set during construction to msg.sender of setUp (this contract).
        // We can distinguish: if the caller (address(this)) is owner, balance may change.
        // But for the fuzzer, we check the general invariant that only the owner can alter balance via burn.
        // More precisely, for any non-owner caller, balance remains unchanged.
        // The fuzzer will find a non-owner address (burner != address(this)) where the bug allows balance reduction.
        if (burner != address(this)) {
            assertTrue(balanceAfter == balanceBefore);
        } else {
            // If caller is owner, we skip the check to avoid false positive; property holds vacuously for owner.
            // This allows the fuzzer to explore only non-owner callers.
            assertTrue(true);
        }
    }
}
